//! The fstp-tls test certificates, embedded at compile time.
//!
//! The files live in `crates/fstp-tls/testdata/` and are regenerated by the
//! `gen.sh` script there. They are test fixtures only. No test runs
//! openssl: every certificate and key here is a committed file.

/// The trusted test CA certificate (PEM). The server certificate, the
/// client certificate and the role certificates chain to it. The test
/// server verifies client certificates against it.
pub const CA_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/ca.pem");

/// The server certificate (PEM), with SAN `localhost`, `127.0.0.1` and `::1`.
pub const SERVER_CERT_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/server.pem");

/// The private key of [`SERVER_CERT_PEM`] (PEM).
pub const SERVER_KEY_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/server-key.pem");

/// A client certificate (PEM) issued by the trusted test CA, CN
/// `fstp-test-client`. No database role has that name, so the test server
/// refuses it for every role.
pub const CLIENT_CERT_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/client.pem");

/// The private key of [`CLIENT_CERT_PEM`] (PEM).
pub const CLIENT_KEY_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/client-key.pem");

/// The client certificate (PEM) of the superuser role `fstp_super`, issued
/// by the trusted test CA, CN `fstp_super`.
pub const SUPERUSER_CERT_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/role-fstp_super.pem");

/// The private key of [`SUPERUSER_CERT_PEM`] (PEM).
pub const SUPERUSER_KEY_PEM: &[u8] =
    include_bytes!("../../fstp-tls/testdata/role-fstp_super-key.pem");

/// The client certificate (PEM) of the role `fstp_app`, issued by the
/// trusted test CA, CN `fstp_app`.
pub const APP_CERT_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/role-fstp_app.pem");

/// The private key of [`APP_CERT_PEM`] (PEM).
pub const APP_KEY_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/role-fstp_app-key.pem");

/// A second CA certificate (PEM) that the test server does not trust.
pub const UNTRUSTED_CA_PEM: &[u8] = include_bytes!("../../fstp-tls/testdata/untrusted-ca.pem");

/// A client certificate (PEM) issued by the untrusted CA.
pub const UNTRUSTED_CLIENT_CERT_PEM: &[u8] =
    include_bytes!("../../fstp-tls/testdata/untrusted-client.pem");

/// The private key of [`UNTRUSTED_CLIENT_CERT_PEM`] (PEM).
pub const UNTRUSTED_CLIENT_KEY_PEM: &[u8] =
    include_bytes!("../../fstp-tls/testdata/untrusted-client-key.pem");
